// Data model: theorems of commutative algebra (MSC 2020 13) and the proofs connecting them, for the theorem graph
// (theorems.html) that looks like the concept graph (concepts.html). Rings are commutative with 1.
//
// Model (see reports/2026-11-03 Satzgraphen aller Gebiete/auftrag.md): id, name, kind, area (five-character MSC class
// or "basic"), field, msc, msc5, premises (the theorems one usual textbook proof uses, named in `proof`; only direct
// premises), formula (quantifier-free core), text, proof, concepts (concepts in the statement, from data/concepts.js or
// with prefix from another folder), year, who. References to other folders use only their anchor theorems
// ("st:zorn-lemma", "ct:snake-lemma"). Results from areas without a folder (linear algebra, field theory) are nodes
// with area "basic". Field theory (12E/12F) is otherwise left out: the concept graph contains only "field".
//
// Prefix for references from other folders: "ca:<id>".
// Sources: Atiyah and Macdonald, Introduction to Commutative Algebra (1969); Matsumura, Commutative Ring Theory (1986);
// Eisenbud, Commutative Algebra with a View Toward Algebraic Geometry (1995).
// Not checked by a specialist.
// Checked by ../../tests/check-theorems.js.
// `fromDefinitions: true` marks a theorem whose usual proof uses only definitions and axioms of its area and no
// theorem (it has no premises); a theorem without premises that rests on theory outside these graphs carries
// `foundation: true`, and its `proof` names that theory. tests/check-theorems.js warns about theorems without
// premises that have neither mark.

window.CA_THEOREMS = {
  title: "Theorems of commutative algebra",

  // areas: the three-character classes, as in the concept graph of the folder (same sectors and colours)
  areas: {
    basic: "Results from other areas without a home folder yet",
    "13A": "13A Rings and ideals",
    "13B": "13B Ring extensions, localization",
    "13C": "13C Modules, dimension",
    "13D": "13D Homological methods",
    "13E": "13E Chain conditions",
    "13F": "13F Special rings",
    "13H": "13H Local rings",
    "13J": "13J Topological rings, completion",
  },

  kinds: { axiom: "Axiom", theorem: "Theorem", lemma: "Lemma", corollary: "Corollary", conjecture: "Conjecture" },

  theorems: [
    // ------------------------------------------------------------ basic (no home folder yet)
    { id: "dickson-lemma", name: "Dickson's lemma", kind: "lemma", area: "basic", field: [13, 6], msc: ["13P", "06A"],
      premises: [],
      fromDefinitions: true,
      text: "Every set of monomials in x<sub>1</sub>, …, x<sub>n</sub> contains finitely many monomials such that every monomial of the set is divisible by one of them; every monomial ideal of k[x<sub>1</sub>, …, x<sub>n</sub>] is generated by finitely many monomials. Equivalently, ℕ<sup>n</sup> with the componentwise order has no infinite antichain.",
      proof: "Induction on n. Forgetting x<sub>n</sub>, by induction finitely many monomials m<sub>1</sub>, …, m<sub>r</sub> of the set M divide every monomial of M up to powers of x<sub>n</sub>; let d be the largest exponent of x<sub>n</sub> in the m<sub>i</sub>. For each j < d the monomials of M with x<sub>n</sub>-exponent j have, again by induction, finitely many members dividing all others. Together these finitely many monomials divide every monomial of M.",
      concepts: ["polynomial-ring", "ideal"], year: 1913, who: "Dickson" },

    // ------------------------------------------------------------ 13A15 Ideals
    { id: "ideal-correspondence", name: "Correspondence theorem for ideals", kind: "lemma", area: "13A", field: [13], msc: ["13A"], msc5: "13A15",
      premises: [],
      fromDefinitions: true,
      foundation: true,
      formula: String.raw`J \mapsto J/I`,
      text: "For an ideal I of R, the ideals of R/I correspond bijectively and inclusion-preservingly to the ideals of R containing I; prime and maximal ideals correspond to prime and maximal ideals.",
      proof: "An ideal J of R/I has the preimage π<sup>−1</sup>(J) ⊇ I, an ideal of R, and π(π<sup>−1</sup>(J)) = J because π is surjective; conversely, for an ideal J′ ⊇ I the image π(J′) is an ideal, since π is surjective, and π<sup>−1</sup>(π(J′)) = J′ + I = J′. Both maps preserve inclusion. J is prime exactly when π<sup>−1</sup>(J) is, because π(a)π(b) ∈ J means ab ∈ π<sup>−1</sup>(J); the maximal ideals are the maximal elements among the proper ideals, and a bijection that preserves inclusion and sends the whole ring to the whole ring preserves them.",
      concepts: ["ideal", "quotient-ring", "prime-ideal", "maximal-ideal"] },
    { id: "existence-of-maximal-ideals", name: "Existence of maximal ideals", kind: "theorem", area: "13A", field: [13], msc: ["13A"], msc5: "13A15",
      premises: ["st:zorn-lemma"],
      proofName: "Zorn's lemma on chains of proper ideals",
      foundation: true,
      formula: String.raw`I \subseteq \mathfrak m`,
      text: "Every proper ideal I of a ring is contained in a maximal ideal 𝔪; in particular every non-zero ring has a maximal ideal and every non-unit lies in one.",
      proof: "The proper ideals containing I, ordered by inclusion, have the union of a chain as upper bound (1 is never in it); Zorn's lemma gives a maximal element.",
      concepts: ["ideal", "maximal-ideal", "unit"], year: 1929, who: "Krull" },
    { id: "maximal-iff-quotient-field", name: "Maximal ideals and fields", kind: "lemma", area: "13A", field: [13], msc: ["13A"], msc5: "13A15",
      premises: ["ideal-correspondence"],
      proofName: "Correspondence of ideals",
      formula: String.raw`\mathfrak m \ \text{maximal} \iff R/\mathfrak m \ \text{field}`,
      text: "An ideal 𝔪 is maximal if and only if R/𝔪 is a field; hence every maximal ideal is prime.",
      proof: "By the correspondence theorem R/𝔪 has only the ideals 0 and R/𝔪 exactly when 𝔪 is maximal, and a ring with only these two ideals is a field.",
      concepts: ["maximal-ideal", "quotient-ring", "ft:field", "prime-ideal"] },
    { id: "prime-ideal-disjoint-from-multiplicative-set", name: "Ideals maximal with respect to avoiding S are prime", kind: "lemma", area: "13A", field: [13], msc: ["13A"], msc5: "13A15",
      premises: ["st:zorn-lemma"],
      proofName: "Zorn's lemma and the product argument",
      formula: String.raw`I \cap S = \emptyset \;\Rightarrow\; I \subseteq \mathfrak p,\ \ \mathfrak p \cap S = \emptyset`,
      text: "For a multiplicative subset S and an ideal I disjoint from S, there is an ideal 𝔭 ⊇ I maximal among the ideals disjoint from S, and every such ideal is prime.",
      proof: "Zorn's lemma gives the maximal ideal 𝔭. If a, b ∉ 𝔭, then 𝔭 + (a) and 𝔭 + (b) meet S, and the product of the two elements of S lies in 𝔭 + (ab), so ab ∉ 𝔭.",
      concepts: ["multiplicative-subset", "ideal", "prime-ideal"], year: 1929, who: "Krull" },
    { id: "nilradical-intersection-of-primes", name: "The nilradical is the intersection of the prime ideals", kind: "theorem", area: "13A", field: [13], msc: ["13A"], msc5: "13A15",
      premises: ["prime-ideal-disjoint-from-multiplicative-set"],
      proofName: "A prime ideal avoiding the powers of f", proofYear: 1929, proofWho: "Krull",
      formula: String.raw`\sqrt{0} = \bigcap_{\mathfrak p} \mathfrak p`,
      text: "The set of nilpotent elements of a ring equals the intersection of all its prime ideals; more generally √I is the intersection of the prime ideals containing I.",
      proof: "A nilpotent element lies in every prime ideal. If f is not nilpotent, S = {1, f, f<sup>2</sup>, …} avoids 0, and an ideal maximal among those disjoint from S is a prime ideal not containing f.",
      concepts: ["nilpotent-element", "radical-ideal", "prime-ideal"], who: "Krull", year: 1929 },
    { id: "jacobson-radical-criterion", name: "Characterisation of the Jacobson radical", kind: "lemma", area: "13A", field: [13], msc: ["13A"], msc5: "13A15",
      premises: ["existence-of-maximal-ideals"],
      proofName: "Maximal ideal containing 1 − xy",
      formula: String.raw`x \in J(R) \iff 1 - xy \in R^\times`,
      text: "An element x lies in the Jacobson radical J(R) if and only if 1 − xy is a unit for every y in R.",
      proof: "If 1 − xy is not a unit, it lies in a maximal ideal 𝔪, and x ∈ 𝔪 would give 1 ∈ 𝔪. Conversely, if x ∉ 𝔪, then 𝔪 + (x) = R, so 1 − xy ∈ 𝔪 for some y.",
      concepts: ["jacobson-radical", "unit"] },
    { id: "prime-avoidance", name: "Prime avoidance", kind: "lemma", area: "13A", field: [13], msc: ["13A"], msc5: "13A15",
      premises: [],
      fromDefinitions: true,
      formula: String.raw`I \subseteq \mathfrak p_1 \cup \dots \cup \mathfrak p_n \;\Rightarrow\; I \subseteq \mathfrak p_i`,
      text: "If an ideal I is contained in the union of finitely many prime ideals 𝔭<sub>1</sub>, …, 𝔭<sub>n</sub>, then it is contained in one of them.",
      proof: "Induction on n. If I lies in none of the 𝔭<sub>i</sub>, by induction there is for each i an element x<sub>i</sub> of I outside all 𝔭<sub>j</sub> with j ≠ i; if some x<sub>i</sub> also lies outside 𝔭<sub>i</sub>, one is done. Otherwise x<sub>1</sub> + x<sub>2</sub>x<sub>3</sub>⋯x<sub>n</sub> lies in I but in no 𝔭<sub>i</sub>, because the 𝔭<sub>i</sub> are prime.",
      concepts: ["ideal", "prime-ideal"] },
    { id: "chinese-remainder-theorem-rings", name: "Chinese remainder theorem for rings", kind: "theorem", area: "13A", field: [13], msc: ["13A"], msc5: "13A15",
      premises: [],
      fromDefinitions: true,
      formula: String.raw`R/(I_1 \cap \dots \cap I_n) \cong R/I_1 \times \dots \times R/I_n`,
      text: "If the ideals I<sub>1</sub>, …, I<sub>n</sub> are pairwise coprime (I<sub>i</sub> + I<sub>j</sub> = R), the natural map gives an isomorphism, and the intersection equals the product of the ideals.",
      proof: "The map R → ∏ R/I<sub>i</sub>, x ↦ (x + I<sub>i</sub>), is a ring homomorphism whose kernel is the intersection of the I<sub>i</sub>, so x + (I<sub>1</sub> ∩ … ∩ I<sub>n</sub>) ↦ (x + I<sub>i</sub>) is well defined and injective. For surjectivity, for i ≠ j write 1 = a<sub>ij</sub> + a<sub>ji</sub> with a<sub>ij</sub> ∈ I<sub>i</sub>. The product e<sub>i</sub> of the a<sub>ji</sub> over j ≠ i is 1 modulo I<sub>i</sub> and 0 modulo every other I<sub>j</sub>, so Σ x<sub>i</sub>e<sub>i</sub> has any given residues. For two coprime ideals, x = xa + xb with a ∈ I, b ∈ J shows I ∩ J ⊆ IJ; induction gives the general case.",
      concepts: ["ideal", "quotient-ring"] },
    { id: "weak-nullstellensatz", name: "Weak Nullstellensatz", kind: "corollary", area: "13A", field: [13, 14], msc: ["13A", "14A"], msc5: "13A15",
      premises: ["zariski-lemma"],
      proofName: "Residue field via Zariski's lemma",
      alternativeProofs: [
        { name: "Dimension count over an uncountable field", premises: ["maximal-iff-quotient-field"],
          idea: "Only for uncountable k: the field K = k[x]/𝔪 has countable dimension over k, while for t ∈ K transcendental over k the elements 1/(t − c), c ∈ k, would be uncountably many linearly independent elements. So K is algebraic over k, hence equal to k, and x<sub>i</sub> − a<sub>i</sub> ∈ 𝔪." },
      ],
      formula: String.raw`\mathfrak m = (x_1 - a_1, \dots, x_n - a_n)`,
      text: "For an algebraically closed field k, every maximal ideal 𝔪 of k[x<sub>1</sub>, …, x<sub>n</sub>] is of this form for a point (a<sub>1</sub>, …, a<sub>n</sub>) of k<sup>n</sup>.",
      proof: "The field k[x]/𝔪 is a finitely generated k-algebra, hence finite over k by Zariski's lemma, hence equal to k; the image a<sub>i</sub> of x<sub>i</sub> gives x<sub>i</sub> − a<sub>i</sub> ∈ 𝔪.",
      concepts: ["maximal-ideal", "polynomial-ring", "ft:field"], year: 1893, who: "Hilbert" },
    { id: "hilbert-nullstellensatz", name: "Hilbert's Nullstellensatz", kind: "theorem", area: "13A", field: [13, 14], msc: ["13A", "14A"], msc5: "13A15",
      premises: ["weak-nullstellensatz", "existence-of-maximal-ideals"],
      proofName: "Rabinowitsch's trick", proofYear: 1929, proofWho: "Rabinowitsch",
      alternativeProofs: [
        { name: "Jacobson rings", premises: ["nilradical-intersection-of-primes", "zariski-lemma", "integral-field-lemma", "weak-nullstellensatz"],
          idea: "√J is the intersection of the prime ideals containing J. For such a prime 𝔭 and f ∉ 𝔭, a maximal ideal of the non-zero finitely generated k-algebra (k[x]/𝔭)[1/f] has a residue field finite over k (Zariski's lemma); its contraction to k[x] is then a prime whose quotient is a domain finite over k, hence a field. So 𝔭 is the intersection of maximal ideals, √J is the intersection of the maximal ideals containing J, and these are the points of V(J) by the weak form.", year: 1951, who: "Krull, Goldman" },
      ],
      formula: String.raw`I\big(V(J)\big) = \sqrt{J}`,
      text: "For an algebraically closed field k and an ideal J of k[x<sub>1</sub>, …, x<sub>n</sub>], the polynomials vanishing on the zero set of J are exactly the elements of the radical of J.",
      proof: "Rabinowitsch's trick: if f vanishes on V(J), the ideal J + (1 − yf) of k[x, y] has no zero; a proper ideal would lie in a maximal ideal, which has a zero by the weak form, so 1 = Σ g<sub>i</sub>h<sub>i</sub> + q(1 − yf), and y = 1/f gives a power of f in J.",
      concepts: ["radical-ideal", "polynomial-ring", "ideal"], year: 1893, who: "Hilbert" },
    { id: "chevalley-shephard-todd", name: "Chevalley–Shephard–Todd theorem", kind: "theorem", foundation: true, area: "13A", field: [13, 20, 5], msc: ["13A", "20F", "05E"], msc5: "13A50",
      premises: ["hilbert-basis-theorem"],
      proofName: "Reynolds operator and grading (Chevalley, Serre)", proofYear: 1955,
      alternativeProofs: [
        { name: "Classification and Molien series (Shephard, Todd)", premises: [], idea: "Shephard and Todd classify the finite complex reflection groups (three infinite families and 34 exceptions) and find in each case invariants with Π d<sub>i</sub> = |G|. The Molien series, an average over characters, shows that the ring of invariants is a polynomial ring if and only if the degrees satisfy this condition and Σ(d<sub>i</sub> − 1) is the number of reflections.", year: 1954, who: "Shephard, Todd" },
      ],
      formula: String.raw`\mathbb C[x_1,\dots,x_n]^G\cong\mathbb C[f_1,\dots,f_n]\iff G=\langle\text{reflections in }G\rangle`,
      text: "For every finite group G ⊆ GL<sub>n</sub>(ℂ) the ring of invariants is a polynomial ring in n homogeneous invariants if and only if G is generated by reflections, elements fixing a hyperplane pointwise. For Weyl groups the degrees of the fundamental invariants are the degrees of the Lie group. Moved here from ../../combinatorics/ on 3 November 2026 (first class 13A50).",
      proof: "The ideal generated by the invariants of positive degree is finitely generated by Hilbert's basis theorem, so homogeneous invariants f<sub>1</sub>, …, f<sub>m</sub> generate it. With the Reynolds operator (averaging over G) and the quotients (f − sf)/(linear form) for reflections s, Chevalley shows that minimal such generators are algebraically independent. The converse (Serre) compares Hilbert series. Averaging requires characteristic 0 and is linear algebra outside these graphs.",
      concepts: ["polynomial-ring", "invariant-ring", "gt:general-linear-group"], year: 1955, who: "Chevalley; Shephard, Todd (1954)" },

    // ------------------------------------------------------------ 13B30 Localization
    { id: "ideals-of-localization", name: "Ideals of a localization", kind: "theorem", area: "13B", field: [13], msc: ["13B"], msc5: "13B30",
      premises: [],
      fromDefinitions: true,
      foundation: true,
      formula: String.raw`\mathfrak q \mapsto \mathfrak q \cap R`,
      text: "Every ideal of S<sup>−1</sup>R is the extension of its contraction to R, and contraction is a bijection from the prime ideals of S<sup>−1</sup>R to the prime ideals of R disjoint from S.",
      proof: "If x/s lies in an ideal J of S<sup>−1</sup>R, then x lies in the contraction of J, so J is the extension of its contraction. For a prime 𝔭 disjoint from S, x/s ∈ S<sup>−1</sup>𝔭 implies ux ∈ 𝔭 for some u in S, hence x ∈ 𝔭; so 𝔭 is the contraction of the prime ideal S<sup>−1</sup>𝔭.",
      concepts: ["localization", "ideal", "prime-ideal", "multiplicative-subset"] },
    { id: "localization-at-prime-is-local", name: "Localization at a prime ideal is local", kind: "corollary", area: "13B", field: [13], msc: ["13B", "13H"], msc5: "13B30",
      premises: ["ideals-of-localization"],
      proofName: "Primes of the localization",
      formula: String.raw`(R_{\mathfrak p},\ \mathfrak p R_{\mathfrak p})`,
      text: "For a prime ideal 𝔭, the ring R<sub>𝔭</sub> is a local ring with maximal ideal 𝔭R<sub>𝔭</sub>; its prime ideals correspond to the prime ideals of R contained in 𝔭.",
      proof: "The prime ideals of R<sub>𝔭</sub> correspond to the primes disjoint from R ∖ 𝔭, that is, contained in 𝔭; the largest of them is 𝔭 itself.",
      concepts: ["localization", "local-ring", "prime-ideal"] },
    { id: "localization-exact", name: "Localization is exact", kind: "theorem", area: "13B", field: [13], msc: ["13B", "13C"], msc5: "13B30",
      premises: [],
      fromDefinitions: true,
      foundation: true,
      formula: String.raw`0 \to S^{-1}M' \to S^{-1}M \to S^{-1}M'' \to 0`,
      text: "For every exact sequence 0 → M′ → M → M″ → 0 of R-modules and every multiplicative subset S, the localized sequence is exact; since S<sup>−1</sup>M ≅ S<sup>−1</sup>R ⊗ M, the ring S<sup>−1</sup>R is a flat R-module.",
      proof: "Only exactness in the middle needs an argument: if m/s maps to 0 in S<sup>−1</sup>M″, then u·g(m) = 0 for some u in S, so um comes from M′ and m/s = um/(us) comes from S<sup>−1</sup>M′. The map S<sup>−1</sup>R ⊗ M → S<sup>−1</sup>M, r/s ⊗ m ↦ rm/s, has an explicit inverse.",
      concepts: ["localization", "flat-module", "ct:exact-sequence"] },
    { id: "local-property-of-zero", name: "Being zero is a local property", kind: "lemma", area: "13B", field: [13], msc: ["13B", "13C"], msc5: "13B30",
      premises: ["existence-of-maximal-ideals"],
      proofName: "Annihilator in a maximal ideal",
      formula: String.raw`M = 0 \iff M_{\mathfrak m} = 0`,
      text: "A module M is zero if and only if its localization M<sub>𝔪</sub> is zero for every maximal ideal 𝔪.",
      proof: "For x ≠ 0 the annihilator of x is a proper ideal, so it lies in some maximal ideal 𝔪, and then x/1 ≠ 0 in M<sub>𝔪</sub>.",
      concepts: ["module", "localization", "maximal-ideal"] },
    { id: "exactness-is-local", name: "Exactness is a local property", kind: "corollary", area: "13B", field: [13], msc: ["13B", "13C"], msc5: "13B30",
      premises: ["local-property-of-zero", "localization-exact"],
      proofName: "Localization of homology",
      formula: String.raw`M' \to M \to M'' \ \text{exact} \iff M'_{\mathfrak m} \to M_{\mathfrak m} \to M''_{\mathfrak m} \ \text{exact}`,
      text: "A sequence of modules is exact if and only if it is exact after localization at every maximal ideal; the same holds for injectivity and surjectivity of a homomorphism.",
      proof: "Localization commutes with taking the homology of the sequence because it is exact; the homology module is zero if and only if all its localizations are.",
      concepts: ["localization", "ct:exact-sequence", "maximal-ideal"] },

    // ------------------------------------------------------------ 13C Modules
    { id: "determinant-trick", name: "Determinant trick (Cayley–Hamilton for modules)", kind: "lemma", area: "13C", field: [13], msc: ["13C"], msc5: "13C05",
      premises: ["la:cramer-rule"],
      proofName: "Adjugate of the matrix of φ",
      formula: String.raw`\varphi^n + a_1 \varphi^{n-1} + \dots + a_n = 0,\quad a_i \in I^i`,
      text: "For a finitely generated R-module M, an ideal I and an endomorphism φ of M with φ(M) ⊆ IM, φ satisfies an equation of this form.",
      proof: "Write φ(m<sub>i</sub>) = Σ a<sub>ij</sub>m<sub>j</sub> for generators m<sub>i</sub> with a<sub>ij</sub> ∈ I; multiplying the matrix (δ<sub>ij</sub>φ − a<sub>ij</sub>) by its adjugate shows that its determinant kills every m<sub>i</sub>.",
      concepts: ["finitely-generated-module", "module-homomorphism", "ideal"] },
    { id: "nakayama-lemma", name: "Nakayama's lemma", kind: "lemma", area: "13C", field: [13], msc: ["13C"], msc5: "13C05",
      premises: ["jacobson-radical-criterion"],
      proofName: "Induction on the number of generators",
      alternativeProofs: [
        { name: "Determinant trick", premises: ["determinant-trick", "jacobson-radical-criterion"],
          idea: "The determinant trick for φ = id gives (1 + a)M = 0 with a ∈ I; since a lies in the Jacobson radical, 1 + a is a unit." },
      ],
      formula: String.raw`IM = M \;\Rightarrow\; M = 0`,
      text: "For a finitely generated module M and an ideal I contained in the Jacobson radical, IM = M implies M = 0.",
      proof: "If M ≠ 0, take a minimal system of generators m<sub>1</sub>, …, m<sub>n</sub>. From m<sub>n</sub> ∈ IM one gets (1 − a)m<sub>n</sub> = a<sub>1</sub>m<sub>1</sub> + … + a<sub>n−1</sub>m<sub>n−1</sub> with a ∈ I; since 1 − a is a unit, m<sub>n</sub> is superfluous, a contradiction.",
      concepts: ["finitely-generated-module", "jacobson-radical"], year: 1951, who: "Nakayama, Krull, Azumaya" },
    { id: "nakayama-generators", name: "Minimal generators of a module over a local ring", kind: "corollary", area: "13C", field: [13], msc: ["13C", "13H"], msc5: "13C05",
      premises: ["nakayama-lemma"],
      proofName: "Nakayama for the quotient by the submodule",
      formula: String.raw`\bar m_1, \dots, \bar m_n \ \text{generate}\ M/\mathfrak m M \;\Rightarrow\; m_1, \dots, m_n \ \text{generate}\ M`,
      text: "For a finitely generated module M over a local ring (R, 𝔪), elements whose images generate the vector space M/𝔪M generate M; every minimal system of generators has dim M/𝔪M elements.",
      proof: "Apply Nakayama's lemma to the quotient of M by the submodule N generated by the m<sub>i</sub>: 𝔪(M/N) = M/N.",
      concepts: ["finitely-generated-module", "local-ring", "residue-field"] },
    { id: "projective-over-local-is-free", name: "Projective modules over local rings are free", kind: "theorem", area: "13C", field: [13], msc: ["13C", "13H"], msc5: "13C10",
      premises: ["nakayama-generators"],
      proofName: "Minimal generators and a split surjection",
      formula: String.raw`P \cong R^n`,
      text: "Every finitely generated projective module P over a local ring is free.",
      proof: "A minimal system of n generators gives a surjection Rⁿ → P that splits, Rⁿ = P ⊕ K; then K/𝔪K = 0 by counting dimensions over the residue field, and K = 0 by Nakayama.",
      concepts: ["projective-module", "free-module", "local-ring"], year: 1958, who: "Kaplansky" },
    { id: "tensor-right-exact", name: "The tensor product is right exact", kind: "theorem", area: "13C", field: [13], msc: ["13C"], msc5: "13C99",
      premises: ["ct:adjoints-preserve-limits"],
      proofName: "Left adjoint of Hom",
      alternativeProofs: [
        { name: "Direct check with the universal property", premises: [],
          idea: "Surjectivity of M ⊗ N → M″ ⊗ N holds on generators m ⊗ n. For exactness in the middle, the map (m″, n) ↦ class of m ⊗ n, with m any preimage of m″, is well defined and bilinear on M″ × N, so it gives an inverse of M ⊗ N / im(M′ ⊗ N) → M″ ⊗ N." },
      ],
      formula: String.raw`M' \otimes N \to M \otimes N \to M'' \otimes N \to 0`,
      text: "For every exact sequence M′ → M → M″ → 0 of R-modules and every module N, the tensored sequence is exact.",
      proof: "The functor − ⊗ N is left adjoint to Hom(N, −) by the universal property of the tensor product, so it preserves colimits, in particular cokernels.",
      concepts: ["tensor-product", "ct:exact-sequence"] },
    { id: "structure-theorem-pid", name: "Structure theorem for modules over a principal ideal domain", kind: "theorem", area: "13C", field: [13], msc: ["13C", "13F"], msc5: "13C05",
      premises: ["smith-normal-form", "fg-modules-noetherian"],
      proofName: "Presentation matrix in Smith normal form",
      alternativeProofs: [
        { name: "Torsion part and primary components", premises: ["fg-modules-noetherian", "pid-is-noetherian", "pid-is-ufd", "chinese-remainder-theorem-rings"],
          idea: "M/torsion is finitely generated and torsion-free, hence free, so M ≅ R<sup>r</sup> ⊕ T. The torsion module T is the direct sum of its p-primary parts for the finitely many primes p dividing its annihilator; each p-primary part splits off cyclic summands of maximal order one by one. The Chinese remainder theorem converts between R/(p<sub>1</sub><sup>e<sub>1</sub></sup>) ⊕ … and R/(d)." },
      ],
      formula: String.raw`M \cong R^r \oplus R/(d_1) \oplus \dots \oplus R/(d_k),\quad d_1 \mid d_2 \mid \dots \mid d_k`,
      text: "Every finitely generated module M over a principal ideal domain R is of this form; r and the ideals (d<sub>i</sub>) are uniquely determined. For R = ℤ this is the structure theorem for finitely generated abelian groups.",
      proof: "Write M = Rⁿ/K. Since R is noetherian, K is finitely generated, so M is the cokernel of a matrix; the Smith normal form of this matrix gives the decomposition.",
      concepts: ["finitely-generated-module", "pid", "free-module", "quotient-module"], who: "Frobenius, Stickelberger", year: 1879 },

    // ------------------------------------------------------------ 13E05 Noetherian rings and modules
    { id: "noetherian-equivalent-conditions", name: "Equivalent conditions for noetherian rings", kind: "lemma", area: "13E", field: [13], msc: ["13E"], msc5: "13E05",
      premises: ["st:axiom-of-choice"],
      foundation: true,
      formula: String.raw`\text{ACC} \iff \text{every ideal finitely generated} \iff \text{maximal elements exist}`,
      text: "For a ring R the following are equivalent: every ascending chain of ideals becomes stationary; every ideal is finitely generated; every non-empty set of ideals has a maximal element.",
      proof: "If every ideal is finitely generated, the union of an ascending chain is an ideal whose finitely many generators lie in one member, so the chain becomes stationary. If a non-empty set of ideals had no maximal element, the axiom of choice (in the form of dependent choice) would give a strictly ascending infinite chain. If the maximal condition holds, a maximal finitely generated ideal contained in a given ideal I equals I.",
      concepts: ["noetherian-ring", "ideal"], year: 1921, who: "Noether" },
    { id: "noetherian-modules-exact-sequences", name: "Noetherian modules in exact sequences", kind: "lemma", area: "13E", field: [13], msc: ["13E"], msc5: "13E05",
      premises: [],
      fromDefinitions: true,
      formula: String.raw`0 \to M' \to M \to M'' \to 0`,
      text: "For an exact sequence 0 → M′ → M → M″ → 0, the module M is noetherian if and only if M′ and M″ are; the same holds for artinian modules.",
      proof: "Submodules of M′ and M″ give submodules of M, so chains in M′ and M″ become stationary if M is noetherian. Conversely, for a chain N<sub>1</sub> ⊆ N<sub>2</sub> ⊆ … in M the intersections with M′ and the images in M″ become stationary, and two submodules N ⊆ N′ with the same intersection with M′ and the same image in M″ are equal. The same argument works for descending chains.",
      concepts: ["noetherian-module", "ct:exact-sequence"] },
    { id: "fg-modules-noetherian", name: "Finitely generated modules over noetherian rings are noetherian", kind: "corollary", area: "13E", field: [13], msc: ["13E"], msc5: "13E05",
      premises: ["noetherian-modules-exact-sequences"],
      proofName: "Quotients of free modules of finite rank",
      foundation: true,
      text: "Every finitely generated module over a noetherian ring is a noetherian module; in particular its submodules are finitely generated.",
      proof: "Rⁿ is noetherian by induction on n using 0 → R → Rⁿ → Rⁿ<sup>−1</sup> → 0, and a finitely generated module is a quotient of some Rⁿ.",
      concepts: ["finitely-generated-module", "noetherian-ring", "noetherian-module"] },
    { id: "hilbert-basis-theorem", name: "Hilbert's basis theorem", kind: "theorem", area: "13E", field: [13], msc: ["13E", "13F"], msc5: "13E05",
      premises: ["noetherian-equivalent-conditions"],
      proofName: "Ideals of leading coefficients",
      alternativeProofs: [
        { name: "Dickson's lemma and Gröbner bases", premises: ["dickson-lemma"],
          idea: "Only for R = k a field: for a monomial order, the leading monomials of the elements of an ideal I generate a monomial ideal, which by Dickson's lemma is generated by finitely many of them. Elements g<sub>1</sub>, …, g<sub>s</sub> of I with these leading monomials form a Gröbner basis: division by them leaves remainder 0 for every element of I, so they generate I.", year: 1965, who: "Buchberger" },
      ],
      formula: String.raw`R \ \text{noetherian} \;\Rightarrow\; R[x] \ \text{noetherian}`,
      text: "If R is a noetherian ring, so is the polynomial ring R[x]; hence also R[x<sub>1</sub>, …, x<sub>n</sub>]. Every ideal of k[x<sub>1</sub>, …, x<sub>n</sub>] is finitely generated.",
      proof: "For an ideal I of R[x], the leading coefficients of its elements of degree at most d form ideals of R; finitely many generators of these ideals give, by division, finitely many generators of I.",
      concepts: ["noetherian-ring", "polynomial-ring"], year: 1890, who: "Hilbert" },
    { id: "noetherian-quotient-and-localization", name: "Quotients and localizations of noetherian rings", kind: "lemma", area: "13E", field: [13], msc: ["13E", "13B"], msc5: "13E05",
      premises: ["ideal-correspondence", "ideals-of-localization"],
      proofName: "Contraction of ascending chains",
      text: "Every quotient R/I and every localization S<sup>−1</sup>R of a noetherian ring R is noetherian.",
      proof: "Ideals of R/I correspond to ideals of R containing I, and every ideal of S<sup>−1</sup>R is generated by the image of its contraction, so ascending chains stay stationary.",
      concepts: ["noetherian-ring", "quotient-ring", "localization"] },
    { id: "finitely-generated-algebra-noetherian", name: "Finitely generated algebras over noetherian rings are noetherian", kind: "corollary", area: "13E", field: [13], msc: ["13E", "13B"], msc5: "13E05",
      premises: ["hilbert-basis-theorem", "noetherian-quotient-and-localization"],
      proofName: "Quotient of a polynomial ring",
      text: "Every finitely generated algebra over a noetherian ring, in particular over a field, is a noetherian ring.",
      proof: "Such an algebra is a quotient of R[x<sub>1</sub>, …, x<sub>n</sub>], which is noetherian by the basis theorem.",
      concepts: ["finitely-generated-algebra", "noetherian-ring"] },
    { id: "artin-tate-lemma", name: "Artin–Tate lemma", kind: "lemma", area: "13E", field: [13], msc: ["13E", "13B"], msc5: "13E15",
      premises: ["finitely-generated-algebra-noetherian", "fg-modules-noetherian"],
      proofName: "Finite module over a noetherian subalgebra",
      formula: String.raw`k \subseteq C \subseteq B`,
      text: "Let k be a noetherian ring and k ⊆ C ⊆ B rings such that B is a finitely generated k-algebra and a finitely generated C-module. Then C is a finitely generated k-algebra.",
      proof: "Take algebra generators of B and module generators over C; the finitely many coefficients that express the generators and their products generate a subalgebra C<sub>0</sub> ⊆ C, which is noetherian, and B is a finitely generated C<sub>0</sub>-module. So its submodule C is a finitely generated C<sub>0</sub>-module, hence a finitely generated k-algebra.",
      concepts: ["finitely-generated-algebra", "finitely-generated-module", "noetherian-ring"], year: 1951, who: "Artin, Tate" },
    { id: "radical-power-lemma", name: "An ideal contains a power of its radical", kind: "lemma", area: "13E", field: [13], msc: ["13E"], msc5: "13E05",
      premises: ["noetherian-equivalent-conditions"],
      proofName: "Finitely many generators of the radical",
      formula: String.raw`(\sqrt I)^n \subseteq I`,
      text: "In a noetherian ring every ideal I contains some power of its radical; in particular the nilradical is nilpotent.",
      proof: "The radical is generated by finitely many elements x<sub>1</sub>, …, x<sub>k</sub> with x<sub>i</sub><sup>n<sub>i</sub></sup> ∈ I; a sufficiently high power of the radical is generated by products that each contain such a power.",
      concepts: ["radical-ideal", "noetherian-ring", "nilpotent-element"] },
    { id: "irreducible-ideal-primary", name: "Irreducible ideals are primary", kind: "lemma", area: "13E", field: [13], msc: ["13E", "13A"], msc5: "13E05",
      premises: [],
      fromDefinitions: true,
      text: "In a noetherian ring, an ideal that is not the intersection of two strictly larger ideals is primary: xy ∈ I and x ∉ I imply that a power of y lies in I.",
      proof: "Let xy ∈ I and x ∉ I. The chain (I : y) ⊆ (I : y<sup>2</sup>) ⊆ … becomes stationary at some n. Then I = (I + (x)) ∩ (I + (y<sup>n</sup>)): an element a = i + by<sup>n</sup> of the right side satisfies ay ∈ I, so by<sup>n+1</sup> ∈ I, b ∈ (I : y<sup>n+1</sup>) = (I : y<sup>n</sup>) and a ∈ I. Since I is irreducible and x ∉ I, it follows that y<sup>n</sup> ∈ I.",
      concepts: ["noetherian-ring", "ideal", "radical-ideal"], year: 1921, who: "Noether" },
    { id: "primary-decomposition", name: "Primary decomposition (Lasker–Noether)", kind: "theorem", area: "13E", field: [13], msc: ["13E", "13A"], msc5: "13E05",
      premises: ["irreducible-ideal-primary", "noetherian-equivalent-conditions"],
      proofName: "Decomposition into irreducible ideals", proofYear: 1921, proofWho: "Noether",
      formula: String.raw`I = \mathfrak q_1 \cap \dots \cap \mathfrak q_n`,
      text: "In a noetherian ring every ideal I is a finite intersection of primary ideals 𝔮<sub>i</sub>; the radicals 𝔭<sub>i</sub> = √𝔮<sub>i</sub> are prime ideals.",
      proof: "If some ideal were not a finite intersection of irreducible ideals, a maximal such ideal would be reducible, a contradiction; irreducible ideals are primary.",
      concepts: ["noetherian-ring", "ideal", "prime-ideal", "radical-ideal"], year: 1905, who: "Lasker; Noether (1921)" },
    { id: "uniqueness-of-primary-decomposition", name: "Uniqueness of primary decomposition", kind: "theorem", area: "13E", field: [13], msc: ["13E", "13A"], msc5: "13E05",
      premises: ["primary-decomposition", "ideals-of-localization"],
      proofName: "Associated primes and localization",
      formula: String.raw`\{\mathfrak p_1, \dots, \mathfrak p_n\} = \operatorname{Ass}(R/I)`,
      text: "In a minimal primary decomposition the prime ideals 𝔭<sub>i</sub> (the associated primes) depend only on I, and so do the primary components belonging to the minimal primes among them.",
      proof: "The 𝔭<sub>i</sub> are exactly the primes of the form √(I : x). A component with minimal prime 𝔭 equals the contraction of IR<sub>𝔭</sub>, because localization at 𝔭 removes the other components.",
      concepts: ["prime-ideal", "localization", "noetherian-ring"], year: 1921, who: "Noether" },
    { id: "artin-rees-lemma", name: "Artin–Rees lemma", kind: "lemma", area: "13E", field: [13], msc: ["13E", "13A"], msc5: "13E05",
      premises: ["finitely-generated-algebra-noetherian", "fg-modules-noetherian"],
      proofName: "Rees algebra",
      formula: String.raw`I^n M \cap N = I^{\,n-c}\,(I^c M \cap N)`,
      text: "For an ideal I of a noetherian ring, a finitely generated module M and a submodule N, there is a c such that this holds for all n ≥ c.",
      proof: "The Rees algebra R ⊕ I ⊕ I<sup>2</sup> ⊕ … is a finitely generated R-algebra, hence noetherian; ⊕ (IⁿM ∩ N) is a submodule of the finitely generated module ⊕ IⁿM over it, so it is generated in degrees up to some c.",
      concepts: ["noetherian-ring", "finitely-generated-module", "submodule", "ideal"], year: 1956, who: "Artin, Rees" },
    { id: "krull-intersection-theorem", name: "Krull's intersection theorem", kind: "theorem", area: "13E", field: [13], msc: ["13E", "13J"], msc5: "13E05",
      premises: ["artin-rees-lemma", "nakayama-lemma"],
      proofName: "Artin–Rees and Nakayama", proofYear: 1956,
      alternativeProofs: [
        { name: "Primary decomposition of IN", premises: ["primary-decomposition", "nakayama-lemma"],
          idea: "Written for M = R; for modules the same with primary submodules. Let N = ∩ I<sup>n</sup> and IN = 𝔮<sub>1</sub> ∩ … ∩ 𝔮<sub>r</sub> a primary decomposition. If N ⊄ 𝔮<sub>i</sub>, take x ∈ N ∖ 𝔮<sub>i</sub>; for a ∈ I, ax ∈ IN ⊆ 𝔮<sub>i</sub> forces a ∈ √𝔮<sub>i</sub>, so I<sup>m</sup> ⊆ 𝔮<sub>i</sub> for some m and N ⊆ I<sup>m</sup> ⊆ 𝔮<sub>i</sub>, a contradiction. Hence N = IN, and Nakayama gives N = 0.", who: "Krull" },
      ],
      formula: String.raw`\bigcap_{n} I^n M = 0`,
      text: "For a noetherian ring, an ideal I contained in the Jacobson radical and a finitely generated module M, the intersection of the submodules IⁿM is zero; in particular a noetherian local ring embeds into its completion.",
      proof: "For N = ∩ IⁿM Artin–Rees gives N = IⁿM ∩ N = I(I<sup>n−1</sup>M ∩ N) ⊆ IN, so IN = N and Nakayama gives N = 0.",
      concepts: ["noetherian-ring", "jacobson-radical", "finitely-generated-module", "completion"], year: 1938, who: "Krull" },

    // ------------------------------------------------------------ 13E10 Artinian rings
    { id: "artinian-ring-properties", name: "Basic properties of artinian rings", kind: "lemma", area: "13E", field: [13], msc: ["13E"], msc5: "13E10",
      premises: ["nilradical-intersection-of-primes"],
      proofName: "Artinian domains are fields",
      formula: String.raw`\mathfrak m_1^k \cdots \mathfrak m_n^k = 0`,
      text: "In an artinian ring every prime ideal is maximal, there are only finitely many maximal ideals 𝔪<sub>1</sub>, …, 𝔪<sub>n</sub>, and the nilradical (= Jacobson radical) is nilpotent, so a product of powers of the maximal ideals is zero.",
      proof: "R/𝔭 is an artinian domain, hence a field; a minimal finite intersection of maximal ideals shows there are finitely many. So the nilradical, the intersection of the primes, is the Jacobson radical; a minimal-ideal argument shows that it is nilpotent.",
      concepts: ["artinian-ring", "prime-ideal", "maximal-ideal", "jacobson-radical"] },
    { id: "artinian-iff-noetherian-dim-0", name: "Artinian rings are the noetherian rings of dimension 0", kind: "theorem", area: "13E", field: [13], msc: ["13E", "13C"], msc5: "13E10",
      premises: ["artinian-ring-properties", "primary-decomposition", "noetherian-modules-exact-sequences", "radical-power-lemma"],
      proofName: "Chain of products of maximal ideals",
      formula: String.raw`R \ \text{artinian} \iff R \ \text{noetherian and}\ \dim R = 0`,
      text: "A ring is artinian if and only if it is noetherian of Krull dimension 0.",
      proof: "In both cases a product of maximal ideals 𝔪<sub>1</sub> ⋯ 𝔪<sub>k</sub> is zero (for noetherian rings of dimension 0: finitely many minimal primes by primary decomposition and a nilpotent nilradical). The successive quotients of the chain R ⊇ 𝔪<sub>1</sub> ⊇ 𝔪<sub>1</sub>𝔪<sub>2</sub> ⊇ … are vector spaces, which satisfy ACC exactly when they satisfy DCC.",
      concepts: ["artinian-ring", "noetherian-ring", "krull-dimension"], year: 1939, who: "Akizuki" },

    // ------------------------------------------------------------ 13B21, 13B22 Integral dependence
    { id: "integral-element-criterion", name: "Criterion for integrality", kind: "lemma", area: "13B", field: [13], msc: ["13B"], msc5: "13B21",
      premises: ["determinant-trick"],
      proofName: "Determinant trick for multiplication by b",
      formula: String.raw`b \ \text{integral over}\ A \iff A[b] \ \text{finitely generated}`,
      text: "An element b of an A-algebra is integral over A if and only if A[b] is a finitely generated A-module, if and only if b lies in a subring that is a finitely generated A-module (or acts on a faithful finitely generated A[b]-module).",
      proof: "An integral equation of degree n shows that 1, b, …, b<sup>n−1</sup> generate A[b]; conversely the determinant trick applied to multiplication by b gives a monic equation.",
      concepts: ["integral-element", "finitely-generated-module", "algebra"] },
    { id: "integral-closure-is-ring", name: "Integral elements form a ring", kind: "corollary", area: "13B", field: [13], msc: ["13B"], msc5: "13B21",
      premises: ["integral-element-criterion"],
      proofName: "The finitely generated module A[b, c]",
      text: "The elements of an A-algebra B that are integral over A form a subring, the integral closure of A in B; integrality is transitive: if C is integral over B and B is integral over A, then C is integral over A.",
      proof: "For integral b, c the ring A[b, c] is a finitely generated A-module containing b + c and bc; transitivity in the same way.",
      concepts: ["integral-element", "integral-closure", "integral-extension"] },
    { id: "integral-field-lemma", name: "Integral extensions of fields", kind: "lemma", area: "13B", field: [13], msc: ["13B"], msc5: "13B21",
      premises: ["maximal-iff-quotient-field"],
      formula: String.raw`A \ \text{field} \iff B \ \text{field}`,
      text: "For integral domains A ⊆ B with B integral over A, A is a field if and only if B is a field. Consequently a prime ideal 𝔮 of B is maximal if and only if 𝔮 ∩ A is maximal.",
      proof: "If A is a field and y ≠ 0 in B, take an integral equation of y of least degree; its constant term is non-zero because B is a domain, and dividing by it expresses y<sup>−1</sup> as a polynomial in y. If B is a field and x ≠ 0 in A, then x<sup>−1</sup> ∈ B is integral over A, and multiplying its equation by x<sup>n−1</sup> shows x<sup>−1</sup> ∈ A. For a prime 𝔮 of B the domain B/𝔮 is integral over A/(𝔮 ∩ A); since an ideal is maximal exactly when its quotient is a field, the first part gives the consequence.",
      concepts: ["integral-extension", "integral-domain", "ft:field"] },
    { id: "lying-over", name: "Lying over", kind: "theorem", area: "13B", field: [13], msc: ["13B"], msc5: "13B21",
      premises: ["integral-field-lemma", "existence-of-maximal-ideals", "localization-at-prime-is-local", "localization-exact"],
      proofName: "Localization at 𝔭",
      formula: String.raw`\mathfrak q \cap A = \mathfrak p`,
      text: "For an integral extension A ⊆ B and every prime ideal 𝔭 of A there is a prime ideal 𝔮 of B with 𝔮 ∩ A = 𝔭.",
      proof: "Localize at 𝔭: A<sub>𝔭</sub> ⊆ B<sub>𝔭</sub> is integral and B<sub>𝔭</sub> ≠ 0. A maximal ideal of B<sub>𝔭</sub> contracts to a maximal ideal of the local ring A<sub>𝔭</sub>, which is 𝔭A<sub>𝔭</sub>; contract further to B.",
      concepts: ["integral-extension", "prime-ideal"], year: 1946, who: "Cohen, Seidenberg (Krull 1937)" },
    { id: "incomparability", name: "Incomparability", kind: "lemma", area: "13B", field: [13], msc: ["13B"], msc5: "13B21",
      premises: ["integral-field-lemma", "localization-at-prime-is-local"],
      proofName: "Localization and the field lemma",
      formula: String.raw`\mathfrak q \subseteq \mathfrak q',\ \ \mathfrak q \cap A = \mathfrak q' \cap A \;\Rightarrow\; \mathfrak q = \mathfrak q'`,
      text: "For an integral extension A ⊆ B, two prime ideals of B lying over the same prime of A cannot be strictly contained in each other.",
      proof: "After localizing at 𝔭 = 𝔮 ∩ A both primes lie over the maximal ideal of A<sub>𝔭</sub>, so both are maximal by the field lemma, hence equal.",
      concepts: ["integral-extension", "prime-ideal"], year: 1946, who: "Cohen, Seidenberg" },
    { id: "going-up", name: "Going up", kind: "theorem", area: "13B", field: [13], msc: ["13B"], msc5: "13B21",
      premises: ["lying-over"],
      proofName: "Lying over in the quotient",
      formula: String.raw`\mathfrak q' \supseteq \mathfrak q,\quad \mathfrak q' \cap A = \mathfrak p'`,
      text: "For an integral extension A ⊆ B, prime ideals 𝔭 ⊆ 𝔭′ of A and a prime 𝔮 of B over 𝔭, there is a prime 𝔮′ ⊇ 𝔮 of B over 𝔭′; chains of primes can be lifted upwards.",
      proof: "Apply lying over to the integral extension A/𝔭 ⊆ B/𝔮 and the prime 𝔭′/𝔭.",
      concepts: ["integral-extension", "prime-ideal"], year: 1946, who: "Cohen, Seidenberg" },
    { id: "integral-over-ideal-lemma", name: "Elements integral over an ideal", kind: "lemma", area: "13B", field: [13], msc: ["13B"], msc5: "13B22",
      premises: ["integral-closure-is-ring"],
      proofName: "Conjugates and the minimal polynomial",
      text: "Let A be an integrally closed domain with fraction field K and 𝔭 a prime ideal. If an element of an extension field of K is integral over 𝔭 (satisfies a monic equation with lower coefficients in 𝔭), then the coefficients of its minimal polynomial over K lie in 𝔭.",
      proof: "The conjugates of the element in a splitting field are integral over 𝔭; the coefficients of the minimal polynomial are polynomials in them, hence integral over 𝔭 and in K, hence in A because A is integrally closed, and then in 𝔭.",
      concepts: ["integral-closure", "fraction-field", "prime-ideal"] },
    { id: "going-down", name: "Going down", kind: "theorem", area: "13B", field: [13], msc: ["13B"], msc5: "13B21",
      premises: ["integral-over-ideal-lemma", "ideals-of-localization"],
      proofName: "Contraction from the localization at 𝔮",
      formula: String.raw`\mathfrak q' \subseteq \mathfrak q,\quad \mathfrak q' \cap A = \mathfrak p'`,
      text: "Let A ⊆ B be integral domains, A integrally closed and B integral over A. For primes 𝔭′ ⊆ 𝔭 of A and a prime 𝔮 of B over 𝔭 there is a prime 𝔮′ ⊆ 𝔮 of B over 𝔭′.",
      proof: "It suffices that 𝔭′B<sub>𝔮</sub> ∩ A = 𝔭′, because a prime is a contraction from B<sub>𝔮</sub> exactly under this condition. An element of 𝔭′B<sub>𝔮</sub> ∩ A is shown to lie in 𝔭′ by comparing minimal polynomials with the lemma on elements integral over 𝔭′.",
      concepts: ["integral-extension", "integral-closure", "prime-ideal", "integral-domain"], year: 1946, who: "Cohen, Seidenberg" },
    { id: "localization-of-integral-closure", name: "Integral closure commutes with localization", kind: "lemma", area: "13B", field: [13], msc: ["13B"], msc5: "13B22",
      premises: ["integral-closure-is-ring"],
      proofName: "Clearing denominators",
      formula: String.raw`S^{-1}\bar A = \overline{S^{-1}A}`,
      text: "The localization of the integral closure of A in B is the integral closure of S<sup>−1</sup>A in S<sup>−1</sup>B; in particular localizations of integrally closed domains are integrally closed.",
      proof: "If b/s satisfies a monic equation over S<sup>−1</sup>A, clearing denominators shows that tb is integral over A for some t ∈ S; the other inclusion is direct.",
      concepts: ["integral-closure", "localization"] },
    { id: "dimension-under-integral-extension", name: "Integral extensions preserve dimension", kind: "corollary", area: "13C", field: [13], msc: ["13C", "13B"], msc5: "13C15",
      premises: ["going-up", "incomparability"],
      proofName: "Going up and incomparability",
      formula: String.raw`\dim B = \dim A`,
      text: "If B is integral over its subring A, then A and B have the same Krull dimension.",
      proof: "Chains in B contract to chains in A that stay strict by incomparability; chains in A lift to B by going up.",
      concepts: ["integral-extension", "krull-dimension"] },

    // ------------------------------------------------------------ 13B25 Finitely generated algebras
    { id: "noether-normalization", name: "Noether normalization", kind: "theorem", area: "13B", field: [13], msc: ["13B", "14A"], msc5: "13B25",
      premises: ["integral-closure-is-ring"],
      proofName: "Nagata's substitution", proofYear: 1962, proofWho: "Nagata",
      alternativeProofs: [
        { name: "Linear change of variables", premises: ["integral-closure-is-ring"],
          idea: "Only for infinite k: if the generators satisfy a relation f = 0, a linear substitution x<sub>i</sub> ↦ x<sub>i</sub> − c<sub>i</sub>x<sub>n</sub> with suitable c<sub>i</sub> ∈ k makes the homogeneous part of highest degree of f, and so f, monic in x<sub>n</sub> up to a constant; induction and transitivity of integrality as before. This version also gives the y<sub>i</sub> as linear forms.", year: 1926, who: "Noether" },
      ],
      formula: String.raw`k[y_1, \dots, y_d] \subseteq A \ \text{finite}`,
      text: "For a field k and a finitely generated k-algebra A there are elements y<sub>1</sub>, …, y<sub>d</sub> of A, algebraically independent over k, such that A is a finitely generated module (integral) over k[y<sub>1</sub>, …, y<sub>d</sub>]. Every affine variety is a finite covering of an affine space.",
      proof: "Induction on the number of generators: if they satisfy a relation, a substitution x<sub>i</sub> ↦ x<sub>i</sub> − x<sub>n</sub><sup>r<sub>i</sub></sup> makes the relation monic in x<sub>n</sub>; then A is integral over a subalgebra with fewer generators, and integrality is transitive.",
      concepts: ["finitely-generated-algebra", "polynomial-ring", "integral-extension", "ft:field"], year: 1926, who: "Noether" },
    { id: "zariski-lemma", name: "Zariski's lemma", kind: "theorem", area: "13B", field: [13, 12], msc: ["13B", "12F"], msc5: "13B25",
      premises: ["noether-normalization", "integral-field-lemma"],
      proofName: "Noether normalization and the field lemma",
      alternativeProofs: [
        { name: "Artin–Tate lemma", premises: ["artin-tate-lemma", "gal:transcendence-degree-well-defined"],
          idea: "Let K = k[x<sub>1</sub>, …, x<sub>n</sub>] with transcendence basis x<sub>1</sub>, …, x<sub>r</sub>, and F = k(x<sub>1</sub>, …, x<sub>r</sub>). K is finite over F, so by the Artin–Tate lemma F is a finitely generated k-algebra, F = k[x<sub>1</sub>, …, x<sub>r</sub>][1/g]. For r ≥ 1 an irreducible factor h of 1 + g would have 1/h in it, so h would divide a power of g (unique factorization in the polynomial ring), which is impossible. Hence r = 0 and K is finite over k.", year: 1951, who: "Artin, Tate" },
      ],
      formula: String.raw`[K : k] < \infty`,
      text: "If a field K is finitely generated as an algebra over a subfield k, then K is a finite extension of k. This is a weak form of the Nullstellensatz.",
      proof: "By Noether normalization K is integral over a polynomial ring k[y<sub>1</sub>, …, y<sub>d</sub>]; by the field lemma this polynomial ring is a field, so d = 0.",
      concepts: ["ft:field", "finitely-generated-algebra"], year: 1947, who: "Zariski" },

    // ------------------------------------------------------------ 13C15 Dimension theory
    { id: "krull-principal-ideal-theorem", name: "Krull's principal ideal theorem", kind: "theorem", area: "13C", field: [13], msc: ["13C"], msc5: "13C15",
      premises: ["artinian-iff-noetherian-dim-0", "nakayama-lemma", "noetherian-quotient-and-localization"],
      proofName: "Symbolic powers in an artinian quotient",
      formula: String.raw`\operatorname{ht}\mathfrak p \le 1`,
      text: "In a noetherian ring, every prime ideal 𝔭 minimal over a principal ideal (f) has height at most 1. Geometrically: a hypersurface cuts every component of a variety in codimension at most 1.",
      proof: "Localize at 𝔭; then R/(f) is noetherian of dimension 0, hence artinian, so the chain 𝔮<sup>(n)</sup> + (f) of symbolic powers of a smaller prime 𝔮 becomes stationary. Nakayama gives 𝔮<sup>(n)</sup> = 𝔮<sup>(n+1)</sup>, hence 𝔮ⁿR<sub>𝔮</sub> = 0 and 𝔮 is minimal.",
      concepts: ["noetherian-ring", "principal-ideal", "height", "prime-ideal"], year: 1928, who: "Krull" },
    { id: "krull-height-theorem", name: "Krull's height theorem", kind: "theorem", area: "13C", field: [13], msc: ["13C"], msc5: "13C15",
      premises: ["krull-principal-ideal-theorem", "prime-avoidance"],
      proofName: "Induction on the number of generators",
      formula: String.raw`\operatorname{ht}\mathfrak p \le n`,
      text: "In a noetherian ring, every prime ideal 𝔭 minimal over an ideal generated by n elements has height at most n.",
      proof: "Induction on n: for a prime 𝔮 ⊊ 𝔭 maximal below 𝔭, prime avoidance and the principal ideal theorem in R/(x<sub>1</sub>) and R/𝔮 reduce the number of generators by one.",
      concepts: ["noetherian-ring", "height", "prime-ideal"], year: 1928, who: "Krull" },
    { id: "dimension-local-noetherian-finite", name: "Noetherian local rings have finite dimension", kind: "corollary", area: "13C", field: [13], msc: ["13C", "13H"], msc5: "13C15",
      premises: ["krull-height-theorem", "nakayama-generators"],
      proofName: "Height theorem applied to 𝔪",
      formula: String.raw`\dim R \le \dim_\kappa \mathfrak m/\mathfrak m^2`,
      text: "The Krull dimension of a noetherian local ring (R, 𝔪) is finite and at most the minimal number of generators of 𝔪; moreover dim R/(x) ≥ dim R − 1 for every x in 𝔪.",
      proof: "𝔪 is minimal over itself and is generated by dim 𝔪/𝔪<sup>2</sup> elements (Nakayama); apply the height theorem.",
      concepts: ["local-ring", "krull-dimension", "noetherian-ring", "residue-field"] },
    { id: "dimension-of-polynomial-ring", name: "Dimension of the polynomial ring", kind: "theorem", area: "13C", field: [13], msc: ["13C", "13F"], msc5: "13C15",
      premises: ["noether-normalization", "incomparability"],
      proofName: "Noether normalization and induction",
      formula: String.raw`\dim k[x_1, \dots, x_n] = n`,
      text: "For a field k, the polynomial ring in n variables has Krull dimension n.",
      proof: "The chain 0 ⊂ (x<sub>1</sub>) ⊂ … ⊂ (x<sub>1</sub>, …, x<sub>n</sub>) gives ≥. For ≤, take f ≠ 0 in the second prime of a chain; after the substitution of Noether normalization k[x]/(f) is integral over k[x<sub>1</sub>, …, x<sub>n−1</sub>], and by incomparability the rest of the chain contracts to a strict chain there; induction.",
      concepts: ["polynomial-ring", "krull-dimension", "ft:field"] },
    { id: "dimension-equals-transcendence-degree", name: "Dimension equals transcendence degree", kind: "theorem", area: "13C", field: [13, 14], msc: ["13C", "14A"], msc5: "13C15",
      premises: ["dimension-of-polynomial-ring", "dimension-under-integral-extension", "gal:transcendence-degree-well-defined"],
      proofName: "Noether normalization",
      formula: String.raw`\dim A = \operatorname{trdeg}_k \operatorname{Frac}(A)`,
      text: "For a field k and a finitely generated k-algebra A that is an integral domain, the Krull dimension of A equals the transcendence degree of its field of fractions over k.",
      proof: "By Noether normalization A is integral over k[y<sub>1</sub>, …, y<sub>d</sub>], so dim A = d. The y<sub>i</sub> form a transcendence basis of Frac(A), which is algebraic over k(y<sub>1</sub>, …, y<sub>d</sub>), so d is the transcendence degree.",
      concepts: ["krull-dimension", "finitely-generated-algebra", "integral-domain", "fraction-field"] },

    // ------------------------------------------------------------ 13F Special rings
    { id: "smith-normal-form", name: "Smith normal form", kind: "theorem", area: "13F", field: [13, 15], msc: ["13F", "15A"], msc5: "13F10",
      premises: ["pid-is-noetherian"],
      formula: String.raw`P A Q = \operatorname{diag}(d_1, \dots, d_k, 0, \dots, 0),\quad d_1 \mid \dots \mid d_k`,
      text: "For every matrix A over a principal ideal domain there are invertible matrices P and Q such that PAQ is diagonal with successive divisibility of the diagonal entries.",
      proof: "Row and column operations bring to the top left an entry that divides all entries of its row and column: if the corner entry a does not divide an entry b, an invertible 2 × 2 matrix replaces a by a generator d = ua + vb of the ideal (a, b). Each such step strictly enlarges the principal ideal generated by the corner entry, so the process stops because a principal ideal domain is noetherian. Then one clears the first row and column, adds rows to obtain divisibility of the remaining entries, and continues with the smaller matrix.",
      concepts: ["pid"], year: 1861, who: "Smith" },
    { id: "pid-is-noetherian", name: "Principal ideal domains are noetherian", kind: "lemma", area: "13F", field: [13], msc: ["13F", "13E"], msc5: "13F10",
      premises: ["noetherian-equivalent-conditions"],
      proofName: "Principal ideals are finitely generated",
      text: "Every principal ideal domain is a noetherian ring.",
      proof: "Every ideal is generated by one element, so the criterion of finitely generated ideals applies.",
      concepts: ["pid", "noetherian-ring"] },
    { id: "polynomial-division", name: "Division with remainder for polynomials", kind: "lemma", area: "13F", field: [13], msc: ["13F", "12E"], msc5: "13F20",
      premises: [],
      fromDefinitions: true,
      formula: String.raw`g = q f + r,\quad \deg r < \deg f`,
      text: "Let R be a commutative ring and f a polynomial in R[x] whose leading coefficient is a unit. For every g in R[x] there are unique polynomials q and r with g = qf + r and deg r < deg f. In particular a non-zero polynomial of degree d over a field has at most d roots.",
      proof: "Induction on the degree of g: if deg g ≥ deg f, with leading coefficients c of g and u of f, then g − cu<sup>−1</sup>x<sup>deg g − deg f</sup>f has smaller degree. Uniqueness: if qf + r = q′f + r′, then (q − q′)f = r′ − r, and since u is a unit the degree of (q − q′)f is deg(q − q′) + deg f unless q = q′. For the roots, division by x − a gives g = (x − a)q + g(a); a root b ≠ a of g is a root of q, because a field has no zero divisors, and induction on the degree gives the bound.",
      concepts: ["polynomial-ring", "commutative-ring", "ft:field"] },
    { id: "polynomial-ring-over-field-pid", name: "The polynomial ring in one variable over a field is a PID", kind: "theorem", area: "13F", field: [13], msc: ["13F", "12E"], msc5: "13F10",
      premises: ["polynomial-division"],
      formula: String.raw`I = (f)`,
      text: "For a field k every ideal I of k[x] is generated by a single polynomial f, a non-zero element of least degree in I.",
      proof: "Let f be a non-zero element of least degree in I. Division with remainder by f, possible because the leading coefficient of f is invertible, writes every g in I as qf + r with deg r < deg f; since r lies in I, r = 0.",
      concepts: ["polynomial-ring", "ft:field", "pid"] },
    { id: "pid-is-ufd", name: "Principal ideal domains are factorial", kind: "theorem", area: "13F", field: [13], msc: ["13F"], msc5: "13F15",
      premises: ["pid-is-noetherian"],
      proofName: "ACC on principal ideals; irreducibles are prime",
      text: "Every principal ideal domain is a unique factorization domain.",
      proof: "Existence of factorizations: otherwise ACC on principal ideals fails. Uniqueness: an irreducible p generates a maximal, hence prime, ideal, so p | ab implies p | a or p | b.",
      concepts: ["pid", "ufd", "irreducible-element"] },
    { id: "dvr-characterization", name: "Characterisation of discrete valuation rings", kind: "theorem", area: "13F", field: [13], msc: ["13F", "13H"], msc5: "13F30",
      premises: ["integral-element-criterion", "nakayama-lemma", "radical-power-lemma"],
      proofName: "Inverse of the maximal ideal",
      formula: String.raw`R \ \text{DVR} \iff R \ \text{integrally closed} \iff \mathfrak m \ \text{principal}`,
      text: "For a noetherian local domain (R, 𝔪) of dimension 1, R is a discrete valuation ring if and only if R is integrally closed, if and only if 𝔪 is principal; then every non-zero ideal is a power of 𝔪.",
      proof: "For integrally closed R and 0 ≠ a ∈ 𝔪, some 𝔪ⁿ lies in (a); choosing b ∈ 𝔪<sup>n−1</sup> ∖ (a) and x = a/b, the module x<sup>−1</sup>𝔪 is not contained in 𝔪, since x<sup>−1</sup> would be integral by the criterion; so 𝔪 = (x). Nakayama gives 𝔪ⁿ ≠ 𝔪<sup>n+1</sup>.",
      concepts: ["dvr", "local-ring", "integral-closure", "noetherian-ring", "krull-dimension", "principal-ideal"] },
    { id: "dedekind-unique-factorization", name: "Unique factorization of ideals in Dedekind domains", kind: "theorem", area: "13F", field: [13, 11], msc: ["13F", "11R"], msc5: "13F05",
      premises: ["uniqueness-of-primary-decomposition", "dvr-characterization", "localization-of-integral-closure"],
      proofName: "Localization at the primes",
      alternativeProofs: [
        { name: "Inverse ideals", premises: ["noetherian-equivalent-conditions", "integral-element-criterion", "existence-of-maximal-ideals"],
          idea: "Every non-zero ideal contains a product of non-zero primes (otherwise take a maximal counterexample). For a maximal ideal 𝔭 this gives an element of 𝔭<sup>−1</sup> = {x ∈ K : x𝔭 ⊆ R} outside R, and 𝔭𝔭<sup>−1</sup> = R, because x𝔭 ⊆ 𝔭 would make x integral over R. Then an ideal I ⊆ 𝔭 gives I = 𝔭(𝔭<sup>−1</sup>I) with a strictly larger ideal 𝔭<sup>−1</sup>I, and noetherian induction gives existence and uniqueness of the factorization.", year: 1927, who: "Dedekind; Noether" },
      ],
      formula: String.raw`I = \mathfrak p_1^{e_1} \cdots \mathfrak p_r^{e_r}`,
      text: "In a Dedekind domain every non-zero ideal I is a product of prime ideals, uniquely up to order.",
      proof: "The localizations at non-zero primes are integrally closed noetherian local domains of dimension 1, hence discrete valuation rings, so primary ideals are prime powers. In dimension 1 the associated primes are minimal, so the primary decomposition, and with it the factorization, is unique.",
      concepts: ["dedekind-domain", "prime-ideal", "ideal"], year: 1871, who: "Dedekind" },

    // ------------------------------------------------------------ 13H, 13D Local and homological
    { id: "regular-local-ring-is-domain", name: "Regular local rings are integral domains", kind: "theorem", area: "13H", field: [13], msc: ["13H"], msc5: "13H05",
      premises: ["dimension-local-noetherian-finite"],
      proofName: "Induction on the dimension",
      text: "Every regular local ring is an integral domain.",
      proof: "Induction on d = dim R: choose x ∈ 𝔪 ∖ 𝔪<sup>2</sup> outside the minimal primes (prime avoidance); R/(x) is regular of dimension d − 1, hence a domain, so (x) is prime. A minimal prime 𝔭 ⊆ (x) satisfies 𝔭 = x𝔭, so 𝔭 = 0 by Nakayama.",
      concepts: ["regular-local-ring", "integral-domain"] },
    { id: "regular-implies-cohen-macaulay", name: "Regular local rings are Cohen–Macaulay", kind: "corollary", area: "13H", field: [13], msc: ["13H"], msc5: "13H10",
      premises: ["regular-local-ring-is-domain"],
      proofName: "Quotients by parameters are domains",
      formula: String.raw`\operatorname{depth} R = \dim R`,
      text: "In a regular local ring every regular system of parameters is a regular sequence, so its depth equals its dimension.",
      proof: "Each quotient R/(x<sub>1</sub>, …, x<sub>i</sub>) is again regular, hence a domain, so x<sub>i+1</sub> is a non-zero-divisor on it.",
      concepts: ["regular-local-ring", "cohen-macaulay", "regular-sequence", "depth"] },
    { id: "auslander-buchsbaum-formula", name: "Auslander–Buchsbaum formula", kind: "theorem", area: "13D", field: [13], msc: ["13D", "13H"], msc5: "13D05",
      premises: ["nakayama-generators", "ha:long-exact-sequence-derived-functors"],
      proofName: "Minimal free resolution and induction on depth",
      formula: String.raw`\operatorname{pd} M + \operatorname{depth} M = \operatorname{depth} R`,
      text: "For a noetherian local ring R and a non-zero finitely generated module M of finite projective dimension, this formula holds.",
      proof: "Induction on depth R using a minimal free resolution (built with Nakayama) and the long exact Tor or Ext sequences for multiplication by a non-zero-divisor.",
      concepts: ["projective-dimension", "depth", "local-ring", "finitely-generated-module"], year: 1957, who: "Auslander, Buchsbaum" },

    // ------------------------------------------------------------ 13J Completion
    { id: "completion-exact", name: "Completion is exact on finitely generated modules", kind: "theorem", area: "13J", field: [13], msc: ["13J"], msc5: "13J10",
      premises: ["artin-rees-lemma", "ct:snake-lemma"],
      proofName: "Artin–Rees and inverse limits",
      formula: String.raw`0 \to \hat M' \to \hat M \to \hat M'' \to 0`,
      text: "Over a noetherian ring, I-adic completion is exact on finitely generated modules, and R̂ ⊗ M ≅ M̂; hence R̂ is a flat R-algebra.",
      proof: "By Artin–Rees the I-adic filtration of M restricts to a filtration of M′ equivalent to its own I-adic filtration; the inverse limit of a system of short exact sequences with surjective transition maps is exact by the snake lemma.",
      concepts: ["completion", "flat-module", "finitely-generated-module", "noetherian-ring"] },
    { id: "hensel-lemma", name: "Hensel's lemma", kind: "theorem", area: "13J", field: [13, 11], msc: ["13J", "11S"], msc5: "13J15",
      premises: ["polynomial-ring-over-field-pid"],
      proofName: "Lifting a coprime factorization step by step",
      alternativeProofs: [
        { name: "Newton's iteration", premises: [],
          idea: "Only for a simple root: if f(a<sub>0</sub>) ∈ 𝔪 and f′(a<sub>0</sub>) is a unit, the sequence a<sub>n+1</sub> = a<sub>n</sub> − f(a<sub>n</sub>)/f′(a<sub>n</sub>) satisfies f(a<sub>n</sub>) ∈ 𝔪<sup>2<sup>n</sup></sup> by the Taylor expansion and converges by completeness to the unique root congruent to a<sub>0</sub>." },
      ],
      formula: String.raw`\bar f = g_0 h_0 \;\Rightarrow\; f = g h,\quad \bar g = g_0,\ \bar h = h_0`,
      text: "Let R be a complete local ring with residue field κ and f a monic polynomial over R. If its reduction factors as g<sub>0</sub>h<sub>0</sub> with coprime monic factors, the factorization lifts uniquely to monic g, h over R. In particular a simple root modulo 𝔪 lifts to a root, as in ℤ<sub>p</sub>.",
      proof: "Since κ[x] is a principal ideal domain, coprimality gives a g<sub>0</sub> + b h<sub>0</sub> = 1; with it the factorization is corrected step by step modulo 𝔪ⁿ, and the corrections converge by completeness.",
      concepts: ["henselian-ring", "completion", "local-ring", "residue-field", "polynomial-ring"], year: 1904, who: "Hensel" },
    { id: "cohen-structure-theorem", name: "Cohen structure theorem", kind: "theorem", area: "13J", field: [13], msc: ["13J", "13H"], msc5: "13J10",
      premises: ["hensel-lemma", "st:zorn-lemma", "nakayama-generators"],
      proofName: "Coefficient field and power series",
      formula: String.raw`R \cong k[[x_1, \dots, x_n]]/I`,
      text: "Every complete noetherian local ring containing a field has a coefficient field k and is a quotient of a power series ring over it; in general it is a quotient of a power series ring over a complete discrete valuation ring.",
      proof: "In characteristic 0 a maximal subfield (Zorn's lemma) is a coefficient field, because Hensel's lemma lifts roots of separable polynomials (in characteristic p one uses p-bases); generators of 𝔪 then give a surjection from the power series ring by the complete form of Nakayama's lemma.",
      concepts: ["completion", "local-ring", "noetherian-ring", "dvr"], year: 1946, who: "Cohen" },
  ],
};
